import pandas as pd
import re, json, sys
from datetime import datetime

HERE = '/tmp/pinchbench/45c85aad/agent_workspace/ts'

TOURS = {
    'fearless': 'Fearless Tour',
    'speaknow': 'Speak Now World Tour',
    'red': 'The Red Tour',
    '1989': 'The 1989 World Tour',
    'reputation': 'Reputation Stadium Tour',
    'loverfest': 'Lover Fest',
    'eras': 'The Eras Tour',
}

MONTHS = {m: i+1 for i, m in enumerate(
    ['January','February','March','April','May','June','July','August','September','October','November','December'])}

REF_RE = re.compile(r'\[(?:note\s*)?\d+\]|\[[a-z]\]|\[note\s+[a-z]\]|\[update\]', re.I)
MDY = re.compile(r'([A-Z][a-z]{2,8})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})')
DMY = re.compile(r'(\d{1,2})(?:st|nd|rd|th)?\s+([A-Z][a-z]{2,8})\.?,?\s+(\d{4})')

def clean(v):
    if pd.isna(v):
        return ''
    s = str(v)
    s = REF_RE.sub('', s)
    s = s.replace('\u00a0', ' ').replace('\u200b', '')
    s = re.sub(r'\s+', ' ', s).strip()
    return s

def parse_dates_in_cell(s):
    """Return list of datetimes found in a date cell (usually 1)."""
    out = []
    for m in MDY.finditer(s):
        mon = MONTHS.get(m.group(1))
        if mon:
            try:
                out.append(datetime(int(m.group(3)), mon, int(m.group(2))))
            except ValueError:
                pass
    if not out:
        for m in DMY.finditer(s):
            mon = MONTHS.get(m.group(2))
            if mon:
                try:
                    out.append(datetime(int(m.group(3)), mon, int(m.group(1))))
                except ValueError:
                    pass
    # handle "March 4-5, 2010" or "June 2 – 3, 2011": same month, range of days
    if not out:
        return out
    rng = re.search(r'([A-Z][a-z]{2,8})\.?\s+(\d{1,2})\s*(?:&|and|\u2013|\u2014|-)\s*(\d{1,2}),?\s+(\d{4})', s)
    if rng:
        mon = MONTHS.get(rng.group(1))
        if mon:
            extra = []
            for d in range(int(rng.group(2)), int(rng.group(3)) + 1):
                try:
                    dt = datetime(int(rng.group(4)), mon, d)
                    if dt not in out:
                        extra.append(dt)
                except ValueError:
                    pass
            out.extend(extra)
    return sorted(set(out))

def find_header(t):
    """Find row index + col mapping for a concerts table header."""
    for i in range(min(len(t), 10)):
        cells = [clean(c).lower() for c in t.iloc[i].tolist()]
        if 'date' in cells and any(c.startswith('city') for c in cells) and any(c.startswith('venue') for c in cells):
            mapping = {}
            for j, c in enumerate(cells):
                if c == 'date' and 'date' not in mapping: mapping['date'] = j
                elif c.startswith('city') and 'city' not in mapping: mapping['city'] = j
                elif c.startswith('country') and 'country' not in mapping: mapping['country'] = j
                elif c.startswith('venue') and 'venue' not in mapping: mapping['venue'] = j
            if 'country' in mapping:
                return i, mapping
    return None, None

all_rows = []
warnings = []
for key, tour in TOURS.items():
    tables = pd.read_html(f'{HERE}/{key}.html', header=None)
    n_tables = 0
    for ti, t in enumerate(tables):
        hi, mp = find_header(t)
        if hi is None:
            continue
        n_tables += 1
        for ri in range(hi + 1, len(t)):
            row = t.iloc[ri]
            dcell = clean(row.iloc[mp['date']])
            if not dcell:
                continue
            dts = parse_dates_in_cell(dcell)
            if not dts:
                # leg header or odd row
                if not re.search(r'leg|total|box|note|festival\b', dcell, re.I):
                    warnings.append((tour, ti, ri, 'NODATE', dcell[:80]))
                continue
            city = clean(row.iloc[mp['city']])
            country = clean(row.iloc[mp['country']])
            venue = clean(row.iloc[mp['venue']])
            low_row = ' '.join(clean(x).lower() for x in row.tolist())
            flag = ''
            if 'cancel' in low_row or 'postpon' in low_row:
                flag = 'CANCEL/POSTPONE'
            if len(dts) > 1:
                warnings.append((tour, ti, ri, 'MULTIDATE', dcell))
            for dt in dts:
                all_rows.append({
                    'tour': tour, 'date': dt.strftime('%Y-%m-%d'),
                    'city': city, 'country': country, 'venue': venue, 'flag': flag,
                })
    print(f'{tour}: {n_tables} concert-tables matched, rows so far {sum(1 for r in all_rows if r["tour"]==tour)}')

df = pd.DataFrame(all_rows)
df['dt'] = pd.to_datetime(df['date'])
# filter range
sub = df[(df['dt'] >= '2010-01-01') & (df['dt'] <= '2025-05-01')].copy()
sub = sub.sort_values('dt')
print('\nCounts per tour (in range):')
print(sub.groupby('tour').size())
print('\nCounts per tour (all parsed):')
print(df.groupby('tour').size())
print('\nTotal in range:', len(sub))
dups = sub[sub.duplicated('date', keep=False)]
print('\nDuplicate dates:', len(dups))
if len(dups):
    print(dups[['tour','date','city','venue']].to_string())
print('\nWarnings:')
for w in warnings[:40]:
    print(w)
flagged = sub[sub['flag'] != '']
print('\nFlagged rows:', len(flagged))
if len(flagged):
    print(flagged[['tour','date','city','venue','flag']].to_string())
sub.drop(columns=['dt']).to_json(f'{HERE}/rows.json', orient='records', indent=1)
print('\nSample rows:')
print(sub.head(3).to_string())
print(sub.tail(3).to_string())
